void *dma_alloc_coherent(struct device *dev, size_t size, dma_addr_t *dma_handle, gfp_t flags, struct dma_attrs *attrs)
{
    struct page *pages;
    unsigned long order = get_order(size);
    void *ret;

    if (!dev)
        return NULL;

    if (dev->dma_mask)
        flags |= GFP_DMA;

    pages = alloc_pages(flags, order);
    if (!pages)
        return NULL;

    ret = page_address(pages);
    if (!ret) {
        __free_pages(pages, order);
        return NULL;
    }

    *dma_handle = page_to_phys(pages);
    return ret;
}

void *dma_alloc_coherent(struct device *dev, size_t size, dma_addr_t *dma_handle, gfp_t flags, struct dma_attrs *attrs)
{
    if (!dev)
        return NULL;

    if (!dev->dma_mask)
        return NULL;

    if (dev->coherent_dma_mask)
        flags |= GFP_DMA;

    if (attrs && dma_get_attr(DMA_ATTR_NONCOHERENT, attrs)) {
        /* Fallback to SW IOTLB method if non-coherent attribute is set */
        return NULL;
    }

    return __dma_alloc_coherent(dev, size, dma_handle, flags, attrs);
}

void *dma_alloc_coherent(struct device *dev, size_t size, dma_addr_t *dma_handle, gfp_t flags, struct dma_attrs *attrs)
{
    if (!dev)
        return NULL;

    if (dev->dma_mask && *dev->dma_mask < DMA_BIT_MASK(32))
        flags |= GFP_DMA;

    if (attrs && dma_get_attr(DMA_ATTR_FORCE_CONTIGUOUS, attrs)) {
        return dma_alloc_from_contiguous(dev, size, 1, flags, dma_handle);
    }

    return dma_alloc_noncontiguous(dev, size, flags, dma_handle, attrs);
}

void *allocate_coherent_dma_memory(struct device *dev, size_t size,
                                   dma_addr_t *dma_handle, gfp_t flags,
                                   struct dma_attrs *attrs) {
    int coherent_flag = 0;
    void *memory = NULL;

    if (!dev || !dma_handle) {
        return NULL;
    }

    if (dev->dma_mask && *(dev->dma_mask) <= DMA_BIT_MASK(32)) {
        flags |= GFP_DMA;
    }

    if (attrs && (dma_get_attr(DMA_ATTR_WRITE_COMBINE, attrs))) {
        coherent_flag |= IOMMU_WRITE_COMBINE;
    }

    memory = dma_alloc_coherent(dev, size, dma_handle, flags | coherent_flag, attrs);

    if (!memory) {
        // Fall back to software I/O translation buffer method if allocation fails
        memory = kmalloc(size, flags);
        if (!memory) {
            return NULL;
        }
        *dma_handle = virt_to_phys(memory);
    }

    return memory;
}

void *allocate_coherent_dma_memory(struct device *dev, size_t size, dma_addr_t *dma_handle, gfp_t flags, struct dma_attrs *attrs) {
    void *memory;

    if (!dev || !dma_handle) {
        return NULL;
    }

    if (!dev->dma_mask || !*dev->dma_mask) {
        return NULL;
    }

    if (flags & __GFP_DMA) {
        flags &= ~__GFP_DMA;
        flags |= GFP_DMA;
    }

    memory = dma_alloc_coherent(dev, size, dma_handle, flags);
    if (!memory) {
        return NULL;
    }

    return memory;
}
